<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Cashbook - C-Net Library</title><style>*{box-sizing:border-box}body{font-family:Arial,sans-serif;background:#f5f7fb;margin:0;color:#1f2937}.wrap{max-width:1320px;margin:28px auto;padding:0 18px}.top{display:flex;justify-content:space-between;gap:14px;align-items:center;margin-bottom:18px}.toplinks{display:flex;gap:8px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:340px 1fr;gap:18px}.card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:18px;box-shadow:0 6px 22px rgba(15,23,42,.05)}.field{margin-bottom:12px}input,select,textarea{width:100%;padding:10px;border:1px solid #d1d5db;border-radius:9px;margin-top:5px;background:#fff}.btn{display:inline-block;background:#111827;color:#fff;text-decoration:none;padding:10px 13px;border-radius:9px;border:0;cursor:pointer}.btn.alt{background:#fff;color:#111827;border:1px solid #d1d5db}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:10px;border-bottom:1px solid #edf0f4;text-align:left;font-size:14px;vertical-align:top}.muted{color:#6b7280}.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:12px}.metric-card{background:#fff;border:1px solid #e5e7eb;border-radius:14px;padding:16px;box-shadow:0 5px 18px rgba(15,23,42,.04)}.metric-label{font-size:12px;text-transform:uppercase;letter-spacing:.04em;color:#64748b}.metric{font-size:25px;font-weight:800;margin-top:6px}.good{color:#047857}.bad{color:#b91c1c}.filters{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:8px;align-items:end;margin-bottom:14px}.categories{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-top:12px}.category{background:#f8fafc;border-radius:10px;padding:12px}.adjust{margin-top:8px;padding-top:8px;border-top:1px dashed #d1d5db}.adjust form{display:grid;grid-template-columns:110px 110px 1fr auto;gap:6px;align-items:end}.ref{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px;color:#475569}.pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#eef2ff;font-size:12px}.section-title{display:flex;justify-content:space-between;gap:12px;align-items:center;margin-bottom:12px}.section-title h2{margin:0;font-size:18px}@media(max-width:1050px){.grid{grid-template-columns:1fr}.metrics{grid-template-columns:repeat(2,1fr)}.filters{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.top{align-items:flex-start;flex-direction:column}.metrics,.filters{grid-template-columns:1fr}.adjust form{grid-template-columns:1fr}.table th,.table td{white-space:nowrap}}</style></head><body><div class="wrap">
