<div><div class="card" style="margin-bottom:18px"><div class="section-title"><h2>Expense Ledger</h2><div class="muted">{{ $from->format('d M Y') }} – {{ $to->format('d M Y') }}</div></div><form method="GET" class="filters"><label>Search<input type="text" name="search" value="{{ request('search') }}"></label><label>From<input type="date" name="from" value="{{ $from->toDateString() }}"></label><label>To<input type="date" name="to" value="{{ $to->toDateString() }}"></label><label>Branch<select name="branch_id"><option value="">All Branches</option>@foreach($branches as $branch)<option value="{{ $branch->id }}" @selected($branchId==$branch->id)>{{ $branch->name }}</option>@endforeach</select></label><label>Category<select name="category"><option value="">All Categories</option>@foreach($categories as $category)<option value="{{ $category }}" @selected(request('category')===$category)>{{ $category }}</option>@endforeach</select></label><label>Mode<select name="payment_mode"><option value="">All Modes</option>@foreach(['cash','upi','card','bank_transfer','other'] as $mode)<option value="{{ $mode }}" @selected(request('payment_mode')===$mode)>{{ strtoupper(str_replace('_',' ',$mode)) }}</option>@endforeach</select></label><button class="btn" type="submit">Apply</button><a class="btn alt" href="{{ route('admin.expenses.index') }}">Reset</a></form><div class="categories">@forelse($categoryTotals as $row)<div class="category"><div class="muted">{{ $row->category }}</div><strong>₹{{ number_format((float)$row->total,2) }}</strong></div>@empty<div class="muted">No category totals.</div>@endforelse</div></div>
<div class="card"><div style="overflow:auto"><table class="table"><thead><tr><th>Date</th><th>Branch</th><th>Expense</th><th>Payee</th><th>Payment</th><th>Gross / Net</th><th>Recorded By</th></tr></thead><tbody>@forelse($expenses as $expense)@php($adjusted=(float)$expense->adjustments->sum('amount')) @php($net=max(0,(float)$expense->amount-$adjusted))<tr><td>{{ $expense->expense_date?->format('d M Y') }}</td><td>{{ $expense->branch?->name ?? 'Global' }}</td><td><strong>{{ $expense->category }}</strong>@if($expense->description)<div class="muted">{{ $expense->description }}</div>@endif</td><td>{{ $expense->payee ?: '—' }}</td><td><span class="pill">{{ strtoupper(str_replace('_',' ',$expense->payment_mode)) }}</span>@if($expense->transaction_ref)<div class="ref">{{ $expense->transaction_ref }}</div>@endif</td><td><strong>₹{{ number_format((float)$expense->amount,2) }}</strong>@if($adjusted>0)<div class="muted">Adjusted -₹{{ number_format($adjusted,2) }} · Net ₹{{ number_format($net,2) }}</div>@endif @if($net>0)<div class="adjust"><form method="POST" action="{{ route('admin.expenses.adjustments.store',$expense) }}">@csrf<label>Type<select name="type"><option value="reversal">Reversal</option><option value="correction">Correction</option><option value="refund">Refund</option></select></label><label>Amount<input type="number" name="amount" min="0.01" max="{{ $net }}" step="0.01" required></label><label>Reason<input type="text" name="reason" required></label><button class="btn alt" type="submit">Adjust</button></form></div>@endif</td><td>{{ $expense->creator?->name ?? '—' }}</td></tr>@empty<tr><td colspan="7" class="muted">No expenses recorded.</td></tr>@endforelse</tbody></table></div><div style="margin-top:14px">{{ $expenses->links() }}</div></div></div></div></div></body></html>